 call:{skill:'communication',title:'Make the timing usable',text:'You will flash the choke while the entry waits in cover. Choose the call.',map:'trade',options:[{text:'“Flashing over in three, two, one; swing.”',ok:true,next:'flash',why:'A shared cue makes the utility actionable.'},{text:'“Go!” while throwing an unannounced flash into the entry.',ok:false,next:'bad',why:'The call does not coordinate the flash or protect your teammate’s vision.'}]},
 flash:{skill:'utility',title:'Remove a second angle',text:'The flash opens the near duel, but a distant defender covers the crossing. One smoke remains.',map:'cross',options:[{text:'Block the distant sight line before crossing.',ok:true,next:'duel',why:'Your next fight now has fewer simultaneous threats.'},{text:'Smoke a harmless empty corner because the animation is ready.',ok:false,next:'bad',why:'Utility needs to solve a current problem.'}]},
 duel:{skill:'switching',title:'Transfer the fight',text:'Clear the numbered head targets in order. Confirm each shot before transitioning.',aim:true,next:'hold'},
 bad:{skill:'positioning',title:'An entry stalls',text:'Your entry falls and two defenders can see the lane. You are in cover with no immediate trade window.',map:'cross',options:[{text:'Stay in cover, call the situation, and regroup.',ok:true,next:'end',why:'A closed trade window is a reason to reassess, not chase.'},{text:'Run into both sight lines for revenge.',ok:false,next:'end',why:'You give two defenders a simultaneous exposed fight.'}]},
 hold:{skill:'positioning',title:'Convert the space',text:'Your team plants. You control an angle on the objective and a safe retreat path.',map:'post',options:[{text:'Hold objective control and communicate the remaining coverage.',ok:true,next:'end',why:'Objective pressure now creates value for you.'},{text:'Abandon the objective and chase an unrelated kill.',ok:false,next:'end',why:'The chase surrenders the advantage the entry created.'}]}
