 noise:{skill:'information',title:'Noise is not the objective',text:'You anchor A. A teammate hears one attacker at B, but has not seen the objective. No one is covering A behind you.',map:'rotate',options:[{text:'Call the contact; keep A coverage until stronger evidence arrives.',ok:true,next:'pressure',why:'One contact does not justify abandoning an uncovered site.'},{text:'Announce a full B execute and leave A immediately.',ok:false,next:'recover',why:'You upgrade weak evidence and lose a responsibility.'}]},
