 pressure:{skill:'positioning',title:'The real hit arrives',text:'Three attackers appear at A. You have cover and an exit; a teammate can rotate in six seconds.',map:'post',options:[{text:'Call the count, delay from cover, and survive for support.',ok:true,next:'duel',why:'Delay and information can create a supported defense.'},{text:'Stand in the open to fight all three at once.',ok:false,next:'reset',why:'Multiple exposed lines remove your defensive advantage.'}]},
