 function followThrough(id,game){const val=game==='valorant',objective=val?'spike':'bomb';const reps={
 precision:['Use the in-game practice range or a safe practice server with stationary bots.','Hold a fixed distance. Land 20 first-bullet headshots, resetting the weapon each time.','Count clean first shots and misses. Adjust smoothly before adding speed.'],
 flick:['Place two bots or select two fixed threat angles at a realistic duel distance.','Alternate one deliberate first-bullet headshot on each. Return to a neutral angle between attempts.','Count 20 transfers. Reduce overshoot before asking for a faster acquisition.'],
 tracking:['Use strafing bots or a cooperating partner in a private practice session.','Track the head through reversals without firing for 30 seconds, then repeat with controlled shots.','Keep the same game sensitivity and distance. Review whether the crosshair leads or trails.'],
 switching:['Use two or three bots with clear gaps between them.','Eliminate one before moving to the next; release the trigger during each transition.','Repeat ten sequences and watch for shots wasted between opponents.'],
 placement:['Walk a real map route in a private session. Identify the likely head height at each corner.','Pre-aim each likely defender position before exposing it; include stairs and elevation changes.','Repeat the route slowly, then at normal speed. Review how far each first correction travels.'],
 stopfire:[val?'In the range, strafe, release movement, and test when the first shot becomes accurate.':'On a practice server, strafe, briefly press the opposite direction, and test the first accurate shot.','Repeat 20 left-to-right and 20 right-to-left attempts using the game’s own accuracy feedback.','Avoid holding both directions indefinitely. Validate the timing in the actual game rather than copying this browser’s delay.'],
 burst:[val?'Use your chosen rifle at a fixed distance in the range.':'Use your chosen rifle against a wall or bots on a practice server.','Compare single taps, short bursts, and a longer spray using the game’s real recoil.','Watch the actual impact pattern and recovery. Practice ten resets without shooting before recovery.'],
 peek:['Choose a real corner with a partner or bots on a private map.','Expose one likely angle at a time, pre-aim at head height, settle movement, then shoot.','Review what a second defender could see. Change cover distance and repeat.'],
 utility:[val?'Choose one agent and one map. Rehearse a smoke or flash that helps an actual entry.':'Choose one map. Rehearse a smoke and flash that remove a real defender angle.','Check coverage from the defender’s view, including gaps, teammate exposure, and duration.','Repeat with a teammate on a countdown. Verify landing and timing in the current game version.'],
 economy:['Review three recent buy phases with the team. Record money and existing equipment.','State the shared round plan before choosing your own purchase.','Check drops, required utility, and next-round recovery using current in-game prices.'],
 information:['Review a demo or recorded round and pause before a rotation.','Separate what was seen, heard, last seen, and merely inferred.','Resume the round and test whether your decision preserved necessary coverage.'],
 trading:['Use a partner and a third player or bot in a private session.','Enter on a shared cue from separate supporting lines with a clear view of the same defender.','Test close and wider spacing. Review whether the first duel was actually tradeable.'],
 positioning:['Pause a recorded round before a duel and mark each enemy sight line.','Find the cover or timing that would isolate one opponent while retaining an escape.','Test the position in a private map, then review one similar moment after a live match.'],
 clutch:['Review three post-plant moments. Write the known travel time, '+objective+' time, and defuse condition.','Compare the required time against the remaining clock before choosing a duel.','Rehearse an objective check from safe cover with a partner; verify the current game’s real timings.'],
 communication:['During a private or live team session, use location, confirmed count, objective information, and next action.','Mark uncertainty explicitly: “last seen,” “steps,” and “count unknown.”','Review the recording for repeated calls and audio clutter during teammate clutches.'],
 composure:['Between rounds, identify one controllable execution error rather than changing everything.','Choose one next-round cue, such as settling before the first shot.','After the match, review whether the cue changed your action; take a break when practice quality drops.']};return reps[id]||[];}
 window.TrainingContent={questions,scenarios,pick,shuffle,followThrough};
